/**
 * Cache for single-model baseline results.
 *
 * Stores pre-computed evaluation results for the single-model baseline
 * (response[0] from the ensemble cache, evaluated once). The cache is
 * sample-size independent — it stores results for ALL cached questions.
 * quick-eval filters to the sampled question IDs at load time.
 *
 * Cache key: `{model}_{dataset}.json` (legacy) or
 * `{model}_{dataset}_structured.json` (structured protocol).
 * Cache dir: `packages/eval/.cache/baselines/`
 *
 * Generated by `generate-cache` alongside ensemble responses.
 * Committed to the repo so CI never needs to run single baseline.
 */
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { fileExists, readJsonFile, writeJsonFile } from './io.js';
import type { PromptRunResult } from '../types.js';
import type { AnswerProtocol } from './methodology.js';
import { scoreUnscoredResponses } from './evaluation.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const CACHE_DIR = resolve(__dirname, '../../.cache/baselines');

export interface BaselineCacheFile {
  model: string;
  dataset: string;
  /** Missing on legacy caches. */
  protocol?: AnswerProtocol;
  createdAt: string;
  entries: Array<{ questionId: string; result: PromptRunResult }>;
}

/** File name of a single-model baseline cache. Legacy caches keep their original names. */
export function baselineCacheFileName(model: string, dataset: string, protocol: AnswerProtocol = 'legacy'): string {
  const safeModel = model.replace(/[/:#]/g, '_');
  return `${safeModel}_${dataset}${protocol === 'structured' ? '_structured' : ''}.json`;
}

function cachePath(model: string, dataset: string, protocol: AnswerProtocol): string {
  return resolve(CACHE_DIR, baselineCacheFileName(model, dataset, protocol));
}

/**
 * Load pre-computed single baseline results as a Map<questionId, PromptRunResult>.
 * Returns null if no cache file exists. Responses the cache left unscored
 * (older caches skipped errors and timeouts) are scored wrong with their
 * failure, so the single model's failures count as the ensemble's do.
 */
export async function loadCachedBaseline(
  model: string,
  dataset: string,
  protocol: AnswerProtocol = 'legacy',
): Promise<Map<string, PromptRunResult> | null> {
  const path = cachePath(model, dataset, protocol);
  if (!(await fileExists(path))) return null;
  try {
    const file = await readJsonFile<BaselineCacheFile>(path);
    const map = new Map<string, PromptRunResult>();
    const evaluatorName = file.entries.find((entry) => entry.result.evaluation)?.result.evaluation?.evaluator;
    for (const entry of file.entries) {
      map.set(entry.questionId, scoreUnscoredResponses(entry.result, evaluatorName));
    }
    return map;
  } catch {
    return null;
  }
}

/**
 * Save pre-computed single baseline results. Overwrites any existing cache.
 */
export async function saveCachedBaseline(
  model: string,
  dataset: string,
  results: Array<{ questionId: string; result: PromptRunResult }>,
  protocol: AnswerProtocol = 'legacy',
): Promise<void> {
  const path = cachePath(model, dataset, protocol);
  const file: BaselineCacheFile = {
    model,
    dataset,
    ...(protocol === 'structured' ? { protocol } : {}),
    createdAt: new Date().toISOString(),
    entries: results,
  };
  await writeJsonFile(path, file);
}
